local M = class("PetardShopModel", LikeOO.OODataBase)

function M:onCreate()
    M.super.onCreate(self)
    --self.open_id = self.m_params.open_id
    self:refreshData(self.m_params)
    self:getData()
end

function M:initGiftXlsxData()
    self.m_giftXlsxData = {}
    local flower_shopData = ConfigManager:getCfgByName("flower_shop")
    local versionData = flower_shopData[self.m_version]
    for index, itemData in pairs(versionData) do
        for id, tempData in pairs(itemData) do
            self.m_giftXlsxData[id] = tempData
        end
    end
end

function M:initRebateMoneyData()
    self.m_rebateMoneyData = {}
    local flower_returnData = ConfigManager:getCfgByName("flower_return")
    local versionData = flower_returnData[self.m_version]
    for id, itemData in pairs(versionData) do
        itemData.id = id
        table.insert(self.m_rebateMoneyData, itemData)
    end
    table.sort(self.m_rebateMoneyData, function(itemData1, itemData2)
        if itemData1.id ~= itemData2.id then
            return itemData1.id < itemData2.id
        end
    end)
end

function M:refreshData(m_params)
    self.m_activityData = m_params.activityData or {}
    self.m_openId = self.m_activityData.open_id
    self.m_version = m_params.m_version
    self.m_xlsxActivity = m_params.xlsxActivity
    self.m_mainActivityName = m_params.mainActivityName

    if not self.m_giftXlsxData then
        self:initGiftXlsxData()
    end
    if not self.m_rebateMoneyData then
        self:initRebateMoneyData()
    end
    local serverData = m_params.serverData
    self.m_consume = serverData.consume
    self.m_allShopDatas = {}
    for index, itemData in pairs(serverData.shop_goods) do
        local curIndex = tonumber(index)
        local xlsxData = self.m_giftXlsxData[itemData.gift_id] or {}
        self.m_allShopDatas[curIndex] = {
            index = curIndex,
            gift_id = itemData.gift_id,
            buyCount = itemData.times,
            xlsxData = xlsxData,
            isCanBuy = (itemData.times < xlsxData.times),
        }
    end
end

-- 获取返利数，及 下级花费id
function M:getRebateMoneyAndLastId()
    local rebateCount = 0
    local curId = 0
    local m_rebateMoneyData = self.m_rebateMoneyData
    local m_consume = self.m_consume
    local allCount = #m_rebateMoneyData
    if m_consume <= 0 then
        return 0, 0 
    end
    for i = 1, allCount do
        local itemData = m_rebateMoneyData[i]
        if i == 1 then
            if m_consume <= itemData.count then
                return itemData.return_count, i
            end
        end
        if m_consume > itemData.count then
            rebateCount = itemData.return_count
            curId = i
        else
            break
        end
    end
    if curId >= allCount then
        -- 超过最后一个，就不显示提示文本
        curId = 0
    end
    return rebateCount, curId 
end

function M:onEnter()
end

return M